// newInput builds the insert a Batch queues for in, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLMeetingRfpRepository) newInput(in *meeting_rfpv1.MeetingRfp) (resourceql.CreateInput, *meeting_rfpv1.MeetingRfp, error) {
	var ci resourceql.CreateInput
	id := repox.NewULID()
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "meetingRfps")
		if err != nil {
			return ci, nil, err
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*meeting_rfpv1.MeetingRfp)
	in.Name = FormatMeetingRfpName(id)
	ci = meetingRfpToCreateInput(in)
	ci.Id = id
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

